pub const fn min_by_key<T, F, K>(v1: T, v2: T, mut f: F) -> T
where
    T: [const] Destruct,
    F: [const] FnMut(&T) -> K + [const] Destruct,
    K: [const] Ord + [const] Destruct,
{
    if f(&v2) < f(&v1) { v2 } else { v1 }
